// Minifies the JavaScript and CSS each package ships (ADR-0123). The source a contributor edits is
// src/<Package>/Assets/<name>; what ships is src/<Package>/wwwroot/<name without extension>.min.<ext>
// and its source map, which carries the source itself so a browser's debugger shows it. Both are
// committed, so a build needs no Node: run this after editing a source, and commit what it writes.
//
// Each minified file opens with the SHA-256 of its source, line endings read as LF so a Windows
// checkout hashes the same text. ShippedAssetTests compares it with the source, so a source edited
// without running this fails layer 2 by name.
//
// Each package asks for the files it was built with (ADR-0123, rewritten 2026-10-11), so this also
// writes, beside the files:
//
// - into the script, the SHA-256 of its source, which the module's `stamp` export answers and the
//   grid compares with the one it was built with before it attaches anything (ADR-0021's note of
//   2026-10-11). A file cannot contain its own hash; the source's can be written into the build.
// - at the end of each stylesheet, the two rules of its notice: one that shows a notice carrying
//   this stylesheet's name and any stamp, and one that hides it for the stamp of this source. A
//   product's root renders the notice with the stamp it was built with, so another version's
//   stylesheet shows it, its own hides it, and one not yet loaded shows nothing.
// - src/<Package>/ShippedAssets.g.cs, the package's own record of what it ships: for each file, its
//   path, the first twelve hex digits of the SHA-256 of the file as shipped (the version its address
//   carries) and the source's SHA-256 (its stamp). C# reads it at build time without Node, and
//   ShippedAssetTests checks it against the files.
//
//     cd tools/assets && npm ci && npm run minify
import { build } from 'esbuild';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');

/** Every package's sources, in a fixed order so the output never depends on the file system. */
export const sources = [
    'src/ExChart/Assets/ex-chart.js',
    'src/ExChart/Assets/ex-chart.css',
    'src/ExGrid/Assets/ex-grid.js',
    'src/ExGrid/Assets/ex-grid.css',
    'src/ExGrid.MudBlazor/Assets/mud-ex-grid.css',
    'src/ExPivot/Assets/ex-pivot.css',
    'src/ExPivot.MudBlazor/Assets/mud-ex-pivot.css',
    'src/ExSheet/Assets/ex-sheet.css',
    'src/ExSheet.MudBlazor/Assets/mud-ex-sheet.css',
];

const hashOf = (text) => createHash('sha256').update(text.replace(/\r\n/g, '\n'), 'utf8').digest('hex');

/** The number of hex digits of a shipped file's SHA-256 its address carries (ADR-0123). */
const versionLength = 12;

/** The identifier in the script's source that the build replaces with the source's SHA-256. */
const stampIdentifier = 'EX_SOURCE_SHA256';

/** What each package ships, by kind, for its ShippedAssets.g.cs. */
const shipped = new Map();

for (const source of sources) {
    const input = path.join(repo, source);
    const name = path.basename(source);
    const extension = path.extname(name);
    const minified = `${path.basename(name, extension)}.min${extension}`;
    const outfile = path.join(path.dirname(input), '..', 'wwwroot', minified);
    const text = fs.readFileSync(input, 'utf8');
    const stamp = hashOf(text);
    const banner = `/*! ${name} sha256:${stamp} - generated by tools/assets/minify.mjs (ADR-0123): edit Assets/${name} and run it again */`;
    const isScript = extension === '.js';

    await build({
        entryPoints: [input],
        outfile,
        bundle: false,
        minify: true,
        format: isScript ? 'esm' : undefined,
        target: 'esnext',
        charset: 'utf8',
        legalComments: 'none',
        banner: { [extension.slice(1)]: banner },
        define: isScript ? { [stampIdentifier]: JSON.stringify(stamp) } : undefined,
        sourcemap: 'linked',
        sourcesContent: true,
        logLevel: 'warning',
    });

    // The map names the source as the package's own file, not a path of this checkout.
    const mapFile = `${outfile}.map`;
    const map = JSON.parse(fs.readFileSync(mapFile, 'utf8'));
    map.sources = [name];
    fs.writeFileSync(mapFile, `${JSON.stringify(map)}\n`);

    if (isScript) {
        // The module must answer its stamp, or the grid refuses every copy of it as another
        // version's: a source that lost its `stamp` export, or the identifier, fails here.
        const out = fs.readFileSync(outfile, 'utf8');
        if (!out.includes(`return"${stamp}"`) || !/export\{[^}]*\bas stamp\b/.test(out)) {
            throw new Error(`${source} does not export stamp() answering ${stampIdentifier}; see ADR-0123`);
        }
    } else {
        // The notice's two rules, after everything else in the file and before its map comment.
        // The selector is the contract between versions: a stylesheet of any version shows the
        // notice a root of any other version renders. The notice's look is the source's.
        const notice = `[data-ex-stylesheet="${name}"]`;
        const rules = `${notice}{display:block!important}${notice}[data-ex-stamp="${stamp}"]{display:none!important}\n`;
        const out = fs.readFileSync(outfile, 'utf8');
        const comment = out.lastIndexOf('/*# sourceMappingURL=');
        if (comment < 0) {
            throw new Error(`${outfile} has no source map comment to put the notice's rules before`);
        }
        fs.writeFileSync(outfile, out.slice(0, comment) + rules + out.slice(comment));
    }

    const version = hashOf(fs.readFileSync(outfile, 'utf8')).slice(0, versionLength);
    const pkg = source.split('/')[1];
    const kinds = shipped.get(pkg) ?? {};
    kinds[isScript ? 'Script' : 'Stylesheet'] = { name, path: `_content/${pkg}/${minified}`, version, stamp };
    shipped.set(pkg, kinds);

    const before = fs.statSync(input).size;
    const after = fs.statSync(outfile).size;
    console.log(`${source} -> ${path.relative(repo, outfile)}: ${before} -> ${after} bytes, version ${version}`);
}

// One file per package, in the package's root namespace. Every value it holds is one of the hashes
// above, so writing it again from unchanged sources writes the same bytes.
for (const [pkg, kinds] of shipped) {
    const lines = [
        '// <auto-generated>',
        '// Written by tools/assets/minify.mjs (ADR-0123): do not edit. Edit the package\'s Assets/ and',
        '// run it again, and commit what it writes. ShippedAssetTests checks every value against the files.',
        '// </auto-generated>',
        '',
        `namespace ${pkg};`,
        '',
        '/// <summary>',
        '/// What this build of the package ships, by content (ADR-0123): for each file, where the package',
        '/// serves it, the version its address carries, and the stamp it is checked by.',
        '/// </summary>',
        'internal static class ShippedAssets',
        '{',
    ];
    for (const kind of ['Script', 'Stylesheet']) {
        const file = kinds[kind];
        if (!file) continue;
        lines.push(
            `    /// <summary>Where the package serves <c>${file.name}</c>, minified, under the application's base.</summary>`,
            `    internal const string ${kind}Path = "${file.path}";`,
            '',
            `    /// <summary>The first ${versionLength} hex digits of the SHA-256 of that file as shipped: the version its address carries.</summary>`,
            `    internal const string ${kind}Version = "${file.version}";`,
            '',
            `    /// <summary>The SHA-256 of <c>Assets/${file.name}</c>, which the shipped file names and answers: its stamp.</summary>`,
            `    internal const string ${kind}Stamp = "${file.stamp}";`,
            '',
        );
        if (kind === 'Stylesheet') {
            lines.push(
                `    /// <summary>The source's name, by which the stylesheet's notice rules find this package's notice.</summary>`,
                `    internal const string ${kind}Name = "${file.name}";`,
                '',
            );
        }
    }
    lines.pop();
    lines.push('}', '');
    const file = path.join(repo, 'src', pkg, 'ShippedAssets.g.cs');
    fs.writeFileSync(file, lines.join('\n'));
    console.log(`-> ${path.relative(repo, file)}`);
}
